WITH cleaned AS (SELECT id, category, price, cost, stock_qty, launch_date, tags, supplier_id, CONCAT_WS('/', product_name, brand) AS product_name_brand_key, UPPER(product_name) AS product_name_upper, COALESCE(brand, 'OTHER') AS resolved_brand FROM products WHERE brand IS NOT NULL AND brand = 'Stark') SELECT * FROM (SELECT id, category, price, cost FROM cleaned) src UNPIVOT (val FOR metric IN (price AS PRICE, cost AS COST));
